-- UGS Creators: PostgreSQL stores metadata and object keys only, never media binaries.
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE campaign_status AS ENUM ('SEARCH','NEGOTIATION','BRIEF_ACCEPTED','CONTRACT','CONTENT_CREATION','APPROVAL','PUBLICATION','PAYMENT','COMPLETED','CANCELLED');
CREATE TYPE payment_status AS ENUM ('PENDING','CHECKING_TAX','APPROVED','PROCESSING','PAID','FAILED','CANCELLED');
CREATE TABLE organizations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, legal_name TEXT, inn TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, full_name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('SUPER_ADMIN','ORG_ADMIN','MANAGER','CREATOR')), is_active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE organization_members (organization_id UUID NOT NULL REFERENCES organizations(id), user_id UUID NOT NULL REFERENCES users(id), role TEXT NOT NULL CHECK(role IN ('ORG_ADMIN','MANAGER','VIEWER')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY(organization_id,user_id));
CREATE TABLE creators (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL UNIQUE REFERENCES users(id), display_name TEXT NOT NULL, tax_status TEXT NOT NULL CHECK(tax_status IN ('SELF_EMPLOYED','IP','INDIVIDUAL')), price_list JSONB NOT NULL DEFAULT '{}'::jsonb, audience_metrics JSONB NOT NULL DEFAULT '{}'::jsonb, engagement_rate NUMERIC(7,4), fraud_score NUMERIC(5,2), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE creator_private_data (creator_id UUID PRIMARY KEY REFERENCES creators(id), inn_ciphertext BYTEA, passport_ciphertext BYTEA, bank_details_ciphertext BYTEA, encryption_key_version TEXT NOT NULL, updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE campaigns (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), organization_id UUID NOT NULL REFERENCES organizations(id), name TEXT NOT NULL, status campaign_status NOT NULL DEFAULT 'SEARCH', budget_kopecks BIGINT NOT NULL DEFAULT 0 CHECK(budget_kopecks>=0), currency CHAR(3) NOT NULL DEFAULT 'RUB' CHECK(currency='RUB'), deadline TIMESTAMPTZ, created_by UUID NOT NULL REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_campaign_org_status ON campaigns(organization_id,status);
CREATE TABLE campaign_creators (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), campaign_id UUID NOT NULL REFERENCES campaigns(id), creator_id UUID NOT NULL REFERENCES creators(id), agreed_fee_kopecks BIGINT NOT NULL DEFAULT 0 CHECK(agreed_fee_kopecks>=0), deadline TIMESTAMPTZ, status TEXT NOT NULL DEFAULT 'INVITED', UNIQUE(campaign_id,creator_id));
CREATE TABLE brief_versions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), campaign_id UUID NOT NULL REFERENCES campaigns(id), version_number INT NOT NULL, content JSONB NOT NULL, content_hash TEXT NOT NULL, accepted_by UUID REFERENCES users(id), accepted_at TIMESTAMPTZ, created_by UUID NOT NULL REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(campaign_id,version_number));
CREATE TABLE contracts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), campaign_id UUID NOT NULL REFERENCES campaigns(id), creator_id UUID NOT NULL REFERENCES creators(id), document_type TEXT NOT NULL CHECK(document_type IN ('CONTRACT','ACT')), version_number INT NOT NULL DEFAULT 1, object_key TEXT NOT NULL, sha256 TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'DRAFT', signed_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE rights_grants (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), contract_id UUID NOT NULL REFERENCES contracts(id), territory TEXT NOT NULL DEFAULT 'RU', exclusive BOOLEAN NOT NULL DEFAULT false, amplification_allowed BOOLEAN NOT NULL DEFAULT false, whitelisting_allowed BOOLEAN NOT NULL DEFAULT false, valid_from DATE NOT NULL, valid_until DATE, CHECK(valid_until IS NULL OR valid_until>=valid_from));
CREATE TABLE media_files (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), campaign_id UUID NOT NULL REFERENCES campaigns(id), creator_id UUID REFERENCES creators(id), uploaded_by UUID NOT NULL REFERENCES users(id), original_media_id UUID REFERENCES media_files(id), object_key TEXT NOT NULL UNIQUE, media_type TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'QUARANTINED', size_bytes BIGINT NOT NULL DEFAULT 0, duration_seconds NUMERIC(12,3), width INT, height INT, sha256 TEXT, is_final BOOLEAN NOT NULL DEFAULT false, approved_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_media_campaign_status ON media_files(campaign_id,status);
CREATE TABLE video_processing_jobs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), media_file_id UUID NOT NULL REFERENCES media_files(id), queue_job_id TEXT UNIQUE, status TEXT NOT NULL DEFAULT 'QUEUED', attempts INT NOT NULL DEFAULT 0, error_message TEXT, started_at TIMESTAMPTZ, finished_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE media_comments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), media_file_id UUID NOT NULL REFERENCES media_files(id), author_id UUID NOT NULL REFERENCES users(id), timecode_seconds NUMERIC(12,3) NOT NULL DEFAULT 0, body TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE payments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), campaign_id UUID NOT NULL REFERENCES campaigns(id), creator_id UUID NOT NULL REFERENCES creators(id), amount_kopecks BIGINT NOT NULL CHECK(amount_kopecks>0), tax_withheld_kopecks BIGINT NOT NULL DEFAULT 0 CHECK(tax_withheld_kopecks>=0), currency CHAR(3) NOT NULL DEFAULT 'RUB' CHECK(currency='RUB'), status payment_status NOT NULL DEFAULT 'PENDING', provider TEXT, provider_payment_id TEXT, idempotency_key TEXT NOT NULL UNIQUE, tax_status_checked_at TIMESTAMPTZ, receipt_reference TEXT, paid_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE consents (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id), consent_type TEXT NOT NULL, document_version TEXT NOT NULL, accepted BOOLEAN NOT NULL, accepted_at TIMESTAMPTZ NOT NULL DEFAULT now(), ip_address INET, evidence JSONB NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE audit_log (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, actor_user_id UUID REFERENCES users(id), organization_id UUID REFERENCES organizations(id), action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id UUID, request_id TEXT, ip_address INET, details JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_audit_entity ON audit_log(entity_type,entity_id,created_at DESC);
CREATE TABLE ad_markings (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), campaign_id UUID NOT NULL REFERENCES campaigns(id), creator_id UUID REFERENCES creators(id), ord_provider TEXT NOT NULL, erid TEXT, status TEXT NOT NULL DEFAULT 'PENDING', reporting_payload JSONB, last_error TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE campaign_metrics (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), campaign_id UUID NOT NULL REFERENCES campaigns(id), creator_id UUID REFERENCES creators(id), source TEXT NOT NULL, metric_date DATE NOT NULL, views BIGINT, reach BIGINT, clicks BIGINT, conversions BIGINT, spend_kopecks BIGINT, revenue_kopecks BIGINT, raw_data JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(campaign_id,creator_id,source,metric_date));
